import re
from datetime import datetime, timezone

DEFAULT_PROFILE = (5, 8.0, 30.0)

PROFILES = {
    "catalog": (6, 8.0, 30.0),
    "ledger": (8, 3.0, 60.0),
    "auth": (6, 6.0, 20.0),
    "payments": (3, 1.0, 30.0),
    "ledger-export": (4, 8.0, 10.0),
    "reports": (9, 5.0, 120.0),
    "inventory": (7, 4.0, 90.0),
    "search": (10, 12.0, 45.0),
    "shipping": (8, 3.0, 40.0),
    "media": (5, 8.0, 15.0),
}

RETRYABLE_STATUSES = {429, 502, 503, 504}
IDEMPOTENT_METHODS = {"GET", "HEAD", "OPTIONS", "PUT", "DELETE"}
UNSAFE_METHODS = {"POST", "PATCH"}
DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]
MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun",
          "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
HTTP_DATE = re.compile(
    r"([A-Z][a-z]{2}), ([0-9]{2}) ([A-Z][a-z]{2}) ([0-9]{4}) "
    r"([0-9]{2}):([0-9]{2}):([0-9]{2}) GMT"
)
SECONDS = re.compile(r"[0-9]+")


def _header(headers, name):
    for key, value in (headers or {}).items():
        if key.lower() == name:
            return value
    return None


def _parse_retry_after(value, now):
    if not isinstance(value, str):
        return None
    value = value.strip(" \t")
    if SECONDS.fullmatch(value):
        return float(int(value))
    match = HTTP_DATE.fullmatch(value)
    if not match:
        return None
    day_name, day, month_name, year, hour, minute, second = match.groups()
    if day_name not in DAYS or month_name not in MONTHS:
        return None
    try:
        moment = datetime(
            int(year), MONTHS.index(month_name) + 1, int(day),
            int(hour), int(minute), int(second), tzinfo=timezone.utc,
        )
    except ValueError:
        return None
    if DAYS[moment.weekday()] != day_name:
        return None
    return max(0.0, (moment - now).total_seconds())


def retry_delay(
    method: str,
    request_headers: dict[str, str],
    attempt: int,
    status: int | None,
    response_headers: dict[str, str],
    now: datetime,
) -> float | None:
    """Seconds to wait before the next attempt, or None to give up.

    `attempt` is the number of the attempt that just failed, 1 for the first.
    `status` is None when there was no response (a connection error).
    `now` is the current time, timezone-aware UTC.
    """
    if status is not None and status not in RETRYABLE_STATUSES:
        return None

    method = method.upper()
    if method in UNSAFE_METHODS:
        key = _header(request_headers, "idempotency-key")
        if not isinstance(key, str) or not key.strip():
            return None
    elif method not in IDEMPOTENT_METHODS:
        return None

    service = _header(request_headers, "x-service")
    profile = DEFAULT_PROFILE
    if isinstance(service, str):
        profile = PROFILES.get(service.strip().lower(), DEFAULT_PROFILE)
    max_attempts, cap, max_retry_after = profile

    if attempt >= max_attempts:
        return None

    delay = min(0.25 * 2 ** (attempt - 1), cap)

    if status in (429, 503):
        wait = _parse_retry_after(_header(response_headers, "retry-after"), now)
        if wait is not None:
            if wait > max_retry_after:
                return None
            delay = max(delay, wait)
    return float(delay)
EOF
